CREATE   PROCEDURE [synapse_ce].[usp_Insert_queue]
AS
BEGIN
	INSERT INTO [synapse_ce].[queue]
	(
		[allowemailcredentials],
		[apitil_emailtemplate],
		[businessunitid],
		[businessunitid_entitytype],
		[businessunitidname],
		[createdby],
		[createdby_entitytype],
		[createdbyname],
		[createdbyyominame],
		[createdon],
		[createdonbehalfby],
		[createdonbehalfby_entitytype],
		[createdonbehalfbyname],
		[createdonbehalfbyyominame],
