		[defaultmailbox_entitytype],
		[defaultmailboxname],
		[description],
		[emailaddress],
		[emailpassword],
		[emailrouteraccessapproval],
		[emailusername],
		[entityimage_timestamp],
		[entityimage_url],
		[entityimageid],
		[exchangerate],
		[Id],
