		[msdyn_operatinghourid_entitytype],
		[msdyn_operatinghouridname],
		[msdyn_priority],
		[msdyn_queuetype],
		[msdyn_uniquename],
		[name],
		[numberofitems],
		[numberofmembers],
		[organizationid],
		[organizationid_entitytype],
		[organizationidname],
		[outgoingemaildeliverymethod],
		[overriddencreatedon],
		[ownerid],
		[ownerid_entitytype],
		[owneridname],
		[owneridtype],
		[owneridyominame],
		[owningbusinessunit],
		[owningbusinessunit_entitytype],
		[owningbusinessunitname],
		[owningteam],
		[owningteam_entitytype],
		[owninguser],
		[owninguser_entitytype],
		[primaryuserid],
		[primaryuserid_entitytype],
		[primaryuseridname],
		[primaryuseridyominame],
		[queueid],
		[queuetypecode],
		[queueviewtype],
		[SinkCreatedOn],
		[SinkModifiedOn],
		[statecode],
		[statuscode],
		[transactioncurrencyid],
		[transactioncurrencyid_entitytype],
		[transactioncurrencyidname],
		[versionnumber]
	)
	SELECT 
		stg.[allowemailcredentials],
		stg.[apitil_emailtemplate],
		stg.[businessunitid],
		stg.[businessunitid_entitytype],
		stg.[businessunitidname],
		stg.[createdby],
		stg.[createdby_entitytype],
		stg.[createdbyname],
		stg.[createdbyyominame],
		stg.[createdon],
