		stg.[createdonbehalfbyname],
		stg.[createdonbehalfbyyominame],
		stg.[defaultmailbox],
		stg.[defaultmailbox_entitytype],
		stg.[defaultmailboxname],
		stg.[description],
		stg.[emailaddress],
		stg.[emailpassword],
		stg.[emailrouteraccessapproval],
		stg.[emailusername],
		stg.[entityimage_timestamp],
		stg.[entityimage_url],
		stg.[entityimageid],
		stg.[exchangerate],
		stg.[Id],
		stg.[ignoreunsolicitedemail],
		stg.[importsequencenumber],
		stg.[incomingemaildeliverymethod],
		stg.[incomingemailfilteringmethod],
		stg.[isemailaddressapprovedbyo365admin],
		stg.[isfaxqueue],
		stg.[modifiedby],
		stg.[modifiedby_entitytype],
		stg.[modifiedbyname],
		stg.[modifiedbyyominame],
		stg.[modifiedon],
		stg.[modifiedonbehalfby],
		stg.[modifiedonbehalfby_entitytype],
		stg.[modifiedonbehalfbyname],
		stg.[modifiedonbehalfbyyominame],
		stg.[msdyn_assignmentinputcontractid],
		stg.[msdyn_assignmentinputcontractid_entitytype],
		stg.[msdyn_assignmentinputcontractidname],
		stg.[msdyn_assignmentstrategy],
		stg.[msdyn_isdefaultqueue],
		stg.[msdyn_isomnichannelqueue],
		stg.[msdyn_maxqueuesize],
		stg.[msdyn_operatinghourid],
		stg.[msdyn_operatinghourid_entitytype],
		stg.[msdyn_operatinghouridname],
		stg.[msdyn_priority],
		stg.[msdyn_queuetype],
		stg.[msdyn_uniquename],
		stg.[name],
		stg.[numberofitems],
		stg.[numberofmembers],
		stg.[organizationid],
		stg.[organizationid_entitytype],
		stg.[organizationidname],
		stg.[outgoingemaildeliverymethod],
		stg.[overriddencreatedon],
		stg.[ownerid],
		stg.[ownerid_entitytype],
		stg.[owneridname],
		stg.[owneridtype],
		stg.[owneridyominame],
		stg.[owningbusinessunit],
		stg.[owningbusinessunit_entitytype],
		stg.[owningbusinessunitname],
		stg.[owningteam],
		stg.[owningteam_entitytype],
		stg.[owninguser],
		stg.[owninguser_entitytype],
		stg.[primaryuserid],
		stg.[primaryuserid_entitytype],
		stg.[primaryuseridname],
		stg.[primaryuseridyominame],
		stg.[queueid],
		stg.[queuetypecode],
		stg.[queueviewtype],
		stg.[SinkCreatedOn],
		stg.[SinkModifiedOn],
		stg.[statecode],
		stg.[statuscode],
		stg.[transactioncurrencyid],
		stg.[transactioncurrencyid_entitytype],
		stg.[transactioncurrencyidname],
		stg.[versionnumber]	
	FROM [staging_ce].[queue] stg
		LEFT JOIN [synapse_ce].[queue] tgt
			ON tgt.[id] = stg.[id]
	WHERE tgt.[id] IS NULL
END
